+"use client";
+
+import { useCallback, useEffect, useRef, useState } from "react";
+import { Shield } from "lucide-react";
+import { Card, CardContent } from "@/components/ui/card";
+import { Badge } from "@/components/ui/badge";
+import { Button } from "@/components/ui/button";
+import { Dialog } from "@/components/ui/dialog";
+import { ShimmerSkeleton } from "@/components/ui/shimmer-skeleton";
+import { formatDate } from "@/lib/utils";
+import type { AuditLogEntry } from "@/types/audit-log";
+import type { PaginatedResponse } from "@/types/api";
+
+interface AuditLogTableProps {
+  from: Date;
+  to: Date;
+  userId: string;
+  action: string;
+}
+
+const PAGE_LIMIT = 20;
+
+function statusFromMetadata(metadata: Record<string, unknown> | null) {
+  const status = metadata?.status;
+  return status === "error" ? "error" : status === "success" ? "success" : null;
+}
+
+/**
+ * Audit log table — lists who exported what data and when.
+ *
+ * Loading state uses ShimmerSkeleton per D-005 (PulseLoader is deprecated).
+ * Pagination is cursor-based per D-004 ("Load more" fetches the next page
+ * using the server-provided cursor — no offset/limit).
+ * Supports full keyboard navigation per D-012: ArrowUp/ArrowDown move
+ * between rows, Enter opens the entry detail, Escape clears the selection.
+ */
+export function AuditLogTable({ from, to, userId, action }: AuditLogTableProps) {
+  const [entries, setEntries] = useState<AuditLogEntry[]>([]);
+  const [cursor, setCursor] = useState<string | null>(null);
+  const [hasMore, setHasMore] = useState(false);
+  const [loading, setLoading] = useState(true);
+  const [loadingMore, setLoadingMore] = useState(false);
+  const [error, setError] = useState<{ message: string; help?: string } | null>(null);
+  const [selectedIndex, setSelectedIndex] = useState(-1);
+  const [detailEntry, setDetailEntry] = useState<AuditLogEntry | null>(null);
+  const rowRefs = useRef<(HTMLTableRowElement | null)[]>([]);
+
+  const buildUrl = useCallback(
+    (cursorParam?: string) => {
+      const params = new URLSearchParams();
+      params.set("limit", String(PAGE_LIMIT));
+      params.set("startDate", from.toISOString());
+      params.set("endDate", to.toISOString());
+      if (userId) params.set("userId", userId);
+      if (action) params.set("action", action);
+      if (cursorParam) params.set("cursor", cursorParam);
+      return `/api/audit-log?${params.toString()}`;
+    },
+    [from, to, userId, action]
+  );
+
+  const fetchFirstPage = useCallback(async () => {
+    setLoading(true);
+    setError(null);
+    setSelectedIndex(-1);
+    try {
+      const res = await fetch(buildUrl());
+      if (!res.ok) {
+        const body = await res.json().catch(() => ({}));
+        setError({
+          message: body.error || "Failed to load the audit log.",
+          help: body.help,
+        });
+        setEntries([]);
+        setHasMore(false);
+        setCursor(null);
+        return;
+      }
+      const page: PaginatedResponse<AuditLogEntry> = await res.json();
+      setEntries(page.data);
+      setHasMore(page.hasMore);
+      setCursor(page.nextCursor);
+    } catch {
+      setError({
+        message: "Failed to load the audit log. Please try again.",
+        help: "https://help.example.com/errors/EXPORT_001",
+      });
+    } finally {
+      setLoading(false);
+    }
+  }, [buildUrl]);
+
+  useEffect(() => {
+    fetchFirstPage();
+  }, [fetchFirstPage]);
+
+  const loadMore = async () => {
+    if (!cursor) return;
+    setLoadingMore(true);
+    try {
+      const res = await fetch(buildUrl(cursor));
+      if (!res.ok) return;
+      const page: PaginatedResponse<AuditLogEntry> = await res.json();
+      setEntries((prev) => [...prev, ...page.data]);
+      setHasMore(page.hasMore);
+      setCursor(page.nextCursor);
+    } finally {
+      setLoadingMore(false);
+    }
+  };
+
+  const moveSelection = (nextIndex: number) => {
+    const clamped = Math.max(0, Math.min(entries.length - 1, nextIndex));
+    setSelectedIndex(clamped);
+    rowRefs.current[clamped]?.focus();
+  };
+
+  const handleKeyDown = (e: React.KeyboardEvent<HTMLTableSectionElement>) => {
+    if (entries.length === 0) return;
+
+    switch (e.key) {
+      case "ArrowDown":
+        e.preventDefault();
+        moveSelection(selectedIndex < 0 ? 0 : selectedIndex + 1);
+        break;
+      case "ArrowUp":
+        e.preventDefault();
+        moveSelection(selectedIndex < 0 ? 0 : selectedIndex - 1);
+        break;
+      case "Enter":
+        if (selectedIndex >= 0) {
+          e.preventDefault();
+          setDetailEntry(entries[selectedIndex]);
+        }
+        break;
+      case "Escape":
+        e.preventDefault();
+        setSelectedIndex(-1);
+        break;
+      default:
+        break;
+    }
+  };
+
+  if (loading) {
+    return (
+      <Card>
+        <CardContent className="p-6">
+          <div className="space-y-4">
+            {Array.from({ length: 6 }).map((_, i) => (
+              <div key={i} className="flex items-center gap-4">
+                <ShimmerSkeleton variant="circular" width={32} />
+                <ShimmerSkeleton variant="text" width="20%" />
+                <ShimmerSkeleton variant="text" width="25%" />
+                <ShimmerSkeleton variant="text" width="15%" />
+                <ShimmerSkeleton variant="text" width="20%" />
+              </div>
+            ))}
+          </div>
+        </CardContent>
+      </Card>
+    );
+  }
+
+  if (error) {
+    return (
+      <Card>
+        <CardContent className="flex flex-col items-center gap-2 p-10 text-center">
+          <p className="text-sm font-medium text-gray-900">{error.message}</p>
+          {error.help && (
+            <a
+              href={error.help}
+              target="_blank"
+              rel="noreferrer"
+              className="text-sm text-brand-600 hover:underline"
+            >
+              View help center article
+            </a>
+          )}
+        </CardContent>
+      </Card>
+    );
+  }
+
+  if (entries.length === 0) {
+    return (
+      <Card>
+        <CardContent className="flex flex-col items-center gap-2 p-10 text-center text-gray-500">
+          <Shield className="h-8 w-8 text-gray-300" />
+          <p className="text-sm">No audit log entries match the current filters.</p>
+        </CardContent>
+      </Card>
+    );
+  }
+
+  return (
+    <Card>
+      <div className="overflow-x-auto">
+        <table className="w-full text-left text-sm">
+          <thead className="border-b border-gray-200 text-xs uppercase tracking-wide text-gray-500">
+            <tr>
+              <th className="px-4 py-3 font-medium">User</th>
+              <th className="px-4 py-3 font-medium">Action</th>
+              <th className="px-4 py-3 font-medium">Resource</th>
+              <th className="px-4 py-3 font-medium">Status</th>
+              <th className="px-4 py-3 font-medium">Date</th>
+            </tr>
+          </thead>
+          <tbody onKeyDown={handleKeyDown}>
+            {entries.map((entry, index) => {
+              const status = statusFromMetadata(entry.metadata);
+              const selected = index === selectedIndex;
+              return (
+                <tr
+                  key={entry.id}
+                  ref={(el) => {
+                    rowRefs.current[index] = el;
+                  }}
+                  tabIndex={selected || (selectedIndex === -1 && index === 0) ? 0 : -1}
+                  role="row"
+                  aria-selected={selected}
+                  onFocus={() => setSelectedIndex(index)}
+                  onClick={() => {
+                    setSelectedIndex(index);
+                    setDetailEntry(entry);
+                  }}
+                  className={`cursor-pointer border-b border-gray-100 outline-none last:border-0 hover:bg-gray-50 focus-visible:bg-brand-50 focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-brand-500 ${
+                    selected ? "bg-brand-50" : ""
+                  }`}
+                >
+                  <td className="px-4 py-3">
+                    <div className="font-medium text-gray-900">{entry.userName}</div>
+                    <div className="text-xs text-gray-500">{entry.userEmail}</div>
+                  </td>
+                  <td className="px-4 py-3 text-gray-700">{entry.action}</td>
+                  <td className="px-4 py-3 text-gray-700">
+                    {entry.resourceType}
+                    {entry.resourceId ? ` / ${entry.resourceId}` : ""}
+                  </td>
+                  <td className="px-4 py-3">
+                    {status ? (
+                      <Badge variant={status === "success" ? "success" : "error"}>
+                        {status}
+                      </Badge>
+                    ) : (
+                      <span className="text-gray-400">—</span>
+                    )}
+                  </td>
+                  <td className="px-4 py-3 text-gray-500">{formatDate(entry.createdAt)}</td>
+                </tr>
+              );
+            })}
+          </tbody>
+        </table>
+      </div>
+
+      {hasMore && (
+        <div className="flex justify-center border-t border-gray-100 p-4">
+          <Button variant="secondary" onClick={loadMore} disabled={loadingMore}>
+            {loadingMore ? "Loading..." : "Load more"}
+          </Button>
+        </div>
+      )}
+
+      <Dialog
+        open={detailEntry !== null}
+        onClose={() => setDetailEntry(null)}
+        title="Audit log entry"
+        description={detailEntry ? formatDate(detailEntry.createdAt) : undefined}
+      >
+        {detailEntry && (
+          <dl className="space-y-3 text-sm">
+            <div className="flex justify-between gap-4">
+              <dt className="text-gray-500">User</dt>
+              <dd className="text-right text-gray-900">
+                {detailEntry.userName} ({detailEntry.userEmail})
+              </dd>
+            </div>
+            <div className="flex justify-between gap-4">
+              <dt className="text-gray-500">Action</dt>
+              <dd className="text-right text-gray-900">{detailEntry.action}</dd>
+            </div>
+            <div className="flex justify-between gap-4">
+              <dt className="text-gray-500">Resource</dt>
+              <dd className="text-right text-gray-900">
+                {detailEntry.resourceType}
+                {detailEntry.resourceId ? ` / ${detailEntry.resourceId}` : ""}
+              </dd>
+            </div>
+            <div className="flex justify-between gap-4">
+              <dt className="text-gray-500">IP address</dt>
+              <dd className="text-right text-gray-900">{detailEntry.ipAddress || "—"}</dd>
+            </div>
+            {detailEntry.metadata && (
+              <div>
+                <dt className="mb-1 text-gray-500">Metadata</dt>
+                <dd>
+                  <pre className="overflow-x-auto rounded-md bg-gray-50 p-3 text-xs text-gray-700">
+                    {JSON.stringify(detailEntry.metadata, null, 2)}
+                  </pre>
+                </dd>
+              </div>
+            )}
+          </dl>
+        )}
+      </Dialog>
+    </Card>
+  );
+}
